CREATE TABLE IF NOT EXISTS duranki_training_programme(id VARCHAR(200) PRIMARY KEY,community_id VARCHAR(200) NOT NULL UNIQUE,name TEXT NOT NULL,state VARCHAR(30) NOT NULL,revision INT NOT NULL,modules LONGTEXT NOT NULL,created_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_training_attempt(id VARCHAR(200) PRIMARY KEY,programme_id VARCHAR(200) NOT NULL,user_id VARCHAR(200) NOT NULL,module_id VARCHAR(200) NOT NULL,score INT NOT NULL,passed TINYINT NOT NULL,created_at VARCHAR(40) NOT NULL,FOREIGN KEY(programme_id) REFERENCES duranki_training_programme(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_training_entitlement(id VARCHAR(200) PRIMARY KEY,programme_id VARCHAR(200) NOT NULL,user_id VARCHAR(200) NOT NULL,module_id VARCHAR(200) NOT NULL,amount_cents BIGINT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'ELIGIBLE',created_at VARCHAR(40) NOT NULL,UNIQUE(programme_id,user_id,module_id),FOREIGN KEY(programme_id) REFERENCES duranki_training_programme(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_training_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor VARCHAR(200) NOT NULL,action VARCHAR(100) NOT NULL,record_id VARCHAR(250) NOT NULL,created_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS duranki_training_migration(id INT PRIMARY KEY,source_sha256 CHAR(64) NOT NULL,counts_json LONGTEXT NOT NULL,migrated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
